const lessons=[{"sentences":[{"speaker":"A","text":"We need to organize everything before the charity sale starts next weekend.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.9405833333333335},{"speaker":"B","text":"Although we have little time remaining, we can divide the tasks easily.","position":2,"audioStartSeconds":5.140583333333334,"audioEndSeconds":9.862083333333333},{"speaker":"A","text":"I can design colorful posters if you prefer to handle the social media posts.","position":3,"audioStartSeconds":10.062083333333334,"audioEndSeconds":15.217458333333333},{"speaker":"B","text":"That division works well because graphic design is my strongest skill.","position":4,"audioStartSeconds":15.417458333333334,"audioEndSeconds":20.070291666666666},{"speaker":"A","text":"Who should we ask to collect the donated books from local residents?","position":5,"audioStartSeconds":20.270291666666665,"audioEndSeconds":24.535791666666668},{"speaker":"B","text":"Mark usually drives a large van so he would finish that job quickly.","position":6,"audioStartSeconds":24.735791666666668,"audioEndSeconds":29.349208333333333},{"speaker":"A","text":"He helped us transport heavy boxes successfully during the previous autumn event.","position":7,"audioStartSeconds":29.549208333333333,"audioEndSeconds":34.72958333333333},{"speaker":"B","text":"I will phone him this afternoon to confirm his availability for tomorrow.","position":8,"audioStartSeconds":34.92958333333333,"audioEndSeconds":39.7105},{"speaker":"A","text":"We also need someone to bake homemade biscuits for the refreshment stall.","position":9,"audioStartSeconds":39.9105,"audioEndSeconds":44.35641666666667},{"speaker":"B","text":"Sarah promised to prepare three trays of chocolate cookies before Friday evening.","position":10,"audioStartSeconds":44.556416666666664,"audioEndSeconds":49.491958333333336},{"speaker":"A","text":"That leaves the financial record keeping for us to manage together.","position":11,"audioStartSeconds":49.69195833333333,"audioEndSeconds":54.02183333333333},{"speaker":"B","text":"We should buy a small cash box when we visit the stationery shop.","position":12,"audioStartSeconds":54.221833333333336,"audioEndSeconds":58.641958333333335},{"speaker":"A","text":"Let us meet at the community center tomorrow morning to check our progress.","position":13,"audioStartSeconds":58.84195833333333,"audioEndSeconds":63.46695833333333},{"speaker":"B","text":"That sounds like a sensible plan for keeping everything organized.","position":14,"audioStartSeconds":63.66695833333333,"audioEndSeconds":68.0815}],"questions":[{"prompt":"What is the main purpose of the conversation?","options":["planning a weekend holiday.","organizing tasks for a charity sale.","designing posters for a community center."],"answer":"B","evidenceSentence":1,"evidence":"We need to organize everything before the charity sale starts next weekend.","explanation":"Hai người đang bàn về việc phân chia công việc chuẩn bị cho buổi bán hàng từ thiện.","oralOnly":false},{"prompt":"Why does speaker B agree to design the posters?","options":["because graphic design is her strongest skill.","because she has a large van.","because she enjoys baking biscuits."],"answer":"A","evidenceSentence":4,"evidence":"That division works well because graphic design is my strongest skill.","explanation":"Speaker B nhận việc thiết kế vì đó là sở trường của cô ấy.","oralOnly":false},{"prompt":"Who is suggested to collect the donated books?","options":["Sarah.","Mark.","The community center manager."],"answer":"B","evidenceSentence":6,"evidence":"Mark usually drives a large van so he would finish that job quickly.","explanation":"Mark được đề xuất đi thu gom sách vì anh ấy có xe tải lớn.","oralOnly":false},{"prompt":"What did Sarah promise to prepare?","options":["colorful posters.","financial records.","chocolate cookies."],"answer":"C","evidenceSentence":10,"evidence":"Sarah promised to prepare three trays of chocolate cookies before Friday evening.","explanation":"Sarah hứa sẽ chuẩn bị ba mẻ bánh quy sô-cô-la.","oralOnly":false},{"prompt":"What item do they need to buy at the stationery shop?","options":["a small cash box.","heavy transport boxes.","baking ingredients."],"answer":"A","evidenceSentence":12,"evidence":"We should buy a small cash box when we visit the stationery shop.","explanation":"Họ cần mua một hộp đựng tiền nhỏ khi tới cửa hàng văn phòng phẩm.","oralOnly":false},{"prompt":"What will the speakers do tomorrow morning?","options":["phone Mark about his availability.","meet at the community center to check progress.","visit local residents to collect books."],"answer":"B","evidenceSentence":13,"evidence":"Let us meet at the community center tomorrow morning to check our progress.","explanation":"Họ thống nhất gặp nhau vào sáng mai tại trung tâm cộng đồng để kiểm tra tiến độ.","oralOnly":false}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
